import sys
from io import StringIO

old_stdout = sys.stdout
sys.stdout = StringIO()

try:
    exec_globals = {}
    exec(code, exec_globals)
    output = sys.stdout.getvalue()
finally:
    sys.stdout = old_stdout

if 'extracted_data' not in exec_globals:
    raise AssertionError('Task 7: extracted_data variable not found')

data = exec_globals['extracted_data']

# Should have 5 entries
if len(data) != 5:
    raise AssertionError(f'Task 7: Expected 5 log entries, got {len(data)}')

# Check first entry
first = data[0]
if len(first) != 4:
    raise AssertionError('Task 7: Each entry should have 4 elements (IP, timestamp, method, status)')

if first[0] != '10.0.0.1':
    raise AssertionError(f'Task 7: First IP should be 10.0.0.1, got {first[0]}')
if first[2] != 'GET':
    raise AssertionError(f'Task 7: First method should be GET, got {first[2]}')
if first[3] != '200':
    raise AssertionError(f'Task 7: First status should be 200, got {first[3]}')

# Check output contains table headers
if 'IP Address' not in output or 'Timestamp' not in output or 'Method' not in output or 'Status' not in output:
    raise AssertionError('Task 8: Output missing table headers')

# Check that all IPs appear in output
ips = ['10.0.0.1', '192.168.1.10', '172.16.0.5']
for ip in ips:
    if ip not in output:
        raise AssertionError(f'Task 8: Output missing IP {ip}')

print('TEST_PASSED')
